        p = os.path.join(WORK, "parts", n + ".stl")
        if not os.path.isfile(p):
            raise Bad("parts/%s.stl not found" % n)
        try:
            kernel.load_part(p, MAX_TRIANGLES, MAX_STL_BYTES, 0.005)
        except kernel.FormatError as e:
            raise Bad("parts/%s.stl: %s" % (n, e))
