        shutil.rmtree(SUBMIT)
    os.makedirs(os.path.join(SUBMIT, "parts"))
    shutil.copyfile(os.path.join(WORK, "movement.json"), os.path.join(SUBMIT, "movement.json"))
    for n in names:
